      "requirement_ids": [
        "r4"
      ],
      "prompt": "When evolving a public-facing REST API used by other internal teams, how do you manage breaking changes? Describe your strategy for versioning and deprecation that minimizes disruption for downstream consumers.",
      "answer_outline": "A strong answer discusses API versioning strategies (e.g., URL versioning vs. header versioning), the importance of maintaining backward compatibility for a transition period, and clear communication/deprecation policies. They should mention using tools like contract testing or schema registries to catch breaking changes early.",
      "difficulty": 2
    },
    {
      "requirement_ids": [
        "r2",
        "r1"
      ],
      "prompt": "In your experience with Node.js or Go, how do you handle concurrency and resource management in a long-running backend service to prevent memory leaks or event loop starvation?",
      "answer_outline": "The candidate should demonstrate understanding of the language's runtime (e.g., Go routines/channels vs. Node.js event loop/async patterns). They should discuss monitoring tools, profiling techniques, and architectural patterns like limiting concurrency or using worker pools to maintain stability.",
      "difficulty": 3
    },
    {
      "requirement_ids": [
        "r7"
      ],
      "prompt": "How have you used Terraform to manage infrastructure for a service running on Kubernetes? Specifically, how do you handle environment-specific configurations while keeping your infrastructure code DRY?",
      "answer_outline": "The candidate should discuss using Terraform modules to encapsulate resources, and variable files or workspaces for environment separation. They should touch on the workflow of planning and applying changes, and perhaps mention how they integrate CI/CD pipelines with these tools.",
      "difficulty": 2
    },
    {
      "requirement_ids": [
        "r9"
      ],
      "prompt": "Describe a scenario where you implemented an event-driven architecture using Kafka or NATS. How did you ensure message delivery guarantees and handle failures when a consumer was unable to process an event?",
      "answer_outline": "The candidate should explain their approach to idempotency, dead-letter queues (DLQ), and retry logic. They should discuss the trade-offs between 'at-least-once' and 'exactly-once' delivery semantics and how they monitored the lag or health of the event stream.",
      "difficulty": 3
    }
  ]
